          {
            ++completed_zones;
            break;
          }
        }
        if (!special_count_zone(t_player, deck, &test))
        {
          ++completed_zones;
          break;
        }
      } while (*deck_ptr[t_player] != -1 && (exiled < max || max < 0));
    if (completed_zones > 2)
    {
